// Independent std-only CPU challenges. No model/runtime/CUDA headers or calls.
#include "../budget_writer/durable_budget.hpp"
#include "../budget_writer/stream_writer.hpp"
#include <fstream>
#include <iostream>
#include <functional>
using namespace hs::n1chain;
namespace {
void rejects(const std::function<void()>&fn){bool rejected=false;try{fn();}catch(const std::exception&){rejected=true;}require(rejected,"expected rejection");}
MockBudgetConfig config(const std::string&id){MockBudgetConfig c;c.run_id=id;c.source_sha256=std::string(64,'a');c.deadline_epoch=4102444800.;c.limits={{"requests",2},{"rows",4},{"backend_inits",1},{"models",1},{"contexts",1},{"placements",1}};c.request_rows={{"a",2},{"b",2}};return c;}
CaptureIdentity identity(){return{"independent-mock","a","mock-context",std::string(64,'a'),std::string(64,'b'),std::string(64,'c')};}
std::string contents(const std::string&p){std::ifstream f(p,std::ios::binary);require(bool(f),"expected evidence file");return{std::istreambuf_iterator<char>(f),std::istreambuf_iterator<char>()};}
}
int main(int argc,char**argv){
 require(argc==2,"provide fresh evidence directory");const std::string root=argv[1];checked(::mkdir(root.c_str(),0700),"fresh independent evidence directory");int passed=0;
 auto test=[&](const std::string&name,const std::function<void()>&fn){fn();++passed;std::cout<<"PASS "<<name<<'\n';};
 test("production gate rejects all native entry methods",[]{ProductionGate g;rejects([&]{g.before_backend_init("x");});rejects([&]{g.before_model_load("x");});rejects([&]{g.before_context("x");});rejects([&]{g.before_placement("x");});rejects([&]{g.before_request("x");});rejects([&]{g.before_decode("x",1);});rejects([&]{g.before_mutation("x","trim");});rejects([&]{g.finish_request("x","COMPLETED");});});
 test("SHA uses full standard byte identity",[]{require(Sha256::of("")=="e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855","empty SHA");require(Sha256::of("abc")=="ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad","abc SHA");});
 test("failed attempt retains rows and blocks reentry",[&]{auto c=config("failed");const auto dir=root+"/failed";{DurableMockBudget b(dir,c);b.before_backend_init("worker");b.before_model_load("worker");b.before_context("worker");b.before_placement("worker");b.before_request("a");b.before_decode("a",1);b.finish_request("a","FAILED");require(b.poisoned()&&b.state().counts.at("rows")==1&&b.state().counts.at("requests")==1,"failed consumption retained");rejects([&]{b.before_request("b");});}auto inspected=DurableMockBudget::inspect(dir,c);require(!inspected.execution_authorized&&inspected.state.counts.at("rows")==1,"inspection only");rejects([&]{DurableMockBudget reentry(dir,c);});});
 test("row rejection after prior reservation poisons without refund",[&]{auto c=config("rows");DurableMockBudget b(root+"/rows",c);b.before_request("a");b.before_decode("a",1);rejects([&]{b.before_decode("a",2);});require(b.poisoned()&&b.state().counts.at("rows")==1,"rejected budget terminal and no refund");rejects([&]{b.finish_request("a","COMPLETED");});});
 test("crash-like unsealed attempt is inspection only",[&]{auto c=config("crash");const auto dir=root+"/crash";{DurableMockBudget b(dir,c);b.before_request("a");b.before_decode("a",1);}const auto s=DurableMockBudget::inspect(dir,c);require(!s.execution_authorized&&s.state.active=="a"&&s.status=="UNCLEAN_OR_POISONED_INSPECTION_ONLY_NO_REENTRY","unsealed in-flight attempt cannot resume");rejects([&]{DurableMockBudget r(dir,c);});});
 test("writer directory collision poisons active coordinator",[&]{auto c=config("collision");DurableMockBudget b(root+"/collision-budget",c);b.before_request("a");checked(::mkdir((root+"/collision").c_str(),0700),"seed collision");rejects([&]{StreamCapture w(root,"collision",identity(),{4096,10,64},b);});require(b.poisoned(),"writer constructor failure must poison");});
 test("partial raw writer preserves failure and blocks further work",[&]{auto c=config("partial");DurableMockBudget b(root+"/partial-budget",c);b.before_request("a");b.before_decode("a",1);IO io;io.write=[](int fd,const void*p,std::size_t n){return n==4 ? ssize_t(0) : ::write(fd,p,n);};{StreamCapture w(root,"partial-capture",identity(),{4096,10,64},b,io);w.begin_tensor("vectors","F32LE",{1},{"vocabulary"});const unsigned char finite[4]={0,0,128,63};rejects([&]{w.append_host_chunk(finite,4);});require(w.failed()&&b.poisoned(),"partial writer terminal");rejects([&]{w.commit_manifest("{}\n");});}require(contents(root+"/partial-capture/UNCERTAIN").size()>0,"partial evidence retained");rejects([&]{b.before_request("b");});require(b.state().counts.at("rows")==1,"failed writer does not refund decode");});
 test("synchronous raw copy is stable and receipt stays unqualified",[&]{auto c=config("copy");DurableMockBudget b(root+"/copy-budget",c);b.before_request("a");StreamCapture w(root,"copy-capture",identity(),{8192,10,64},b);w.begin_tensor("vectors","F32LE",{1},{"vocabulary"});unsigned char host[4]={0,0,128,63};w.append_host_chunk(host,4);host[2]=0;host[3]=64;const auto d=w.finish_tensor();require(d.bytes==4&&d.canonical_numeric,"descriptor complete");w.commit_manifest("{\"evidence\":\"SYNTHETIC_CPU_ONLY\"}\n");require(w.committed(),"commit complete");const auto bytes=contents(root+"/copy-capture/vectors.bin");require(bytes.size()==4&&static_cast<unsigned char>(bytes[2])==128&&static_cast<unsigned char>(bytes[3])==63,"caller mutation did not change committed bytes");require(contents(root+"/copy-capture/COMPLETE.json").find("\"native_qualified\":false")!=std::string::npos,"transport never native qualification");b.finish_request("a","COMPLETED");b.seal_success();});
 std::cout<<"{\"tests\":"<<passed<<",\"failures\":0,\"evidence\":\"INDEPENDENT_STD_ONLY_SYNTHETIC\",\"backend_init\":0,\"model_loads\":0,\"native_contexts\":0,\"placements\":0,\"forwards\":0}\n";
}
